    88	
    89	/**
    90	 * 배송 상태 배치 처리를 위한 ItemProcessor
    91	 * 주문 배송 상태를 조회하고 처리합니다.
    92	 */
    93	@Slf4j
    94	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
    95	
    96	    private final PlaywrightBrowserManager browserManager;
    97	    private final NotificationCommandService notificationService;
    98	    private final OrderShipmentCommandService orderService;
    99	
   100	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
   101	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
   102	    private static final int TIMEOUT_MS = 30000; // 30초
   103	
   104	    /**
   105	     * 배송 상태 처리기 생성자
   106	     *
   107	     * @param browserManager Playwright 브라우저 관리자
   108	     * @param notificationService 알림 서비스
   109	     * @param orderService 주문 서비스
   110	     */
   111	    public ShipmentItemProcessor(
   112	            PlaywrightBrowserManager browserManager,
   113	            NotificationCommandService notificationService,
   114	            OrderShipmentCommandService orderService
   115	    ) {
   116	        this.browserManager = browserManager;
   117	        this.notificationService = notificationService;
   118	        this.orderService = orderService;
   119	    }
   120	
   121	    /**
   122	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
   123	     *
   124	     * @param orderShipment 처리할 배송 정보
   125	     * @return 업데이트된 배송 정보
   126	     * @throws Exception 처리 중 오류 발생 시
   127	     */
   128	    @Override
   129	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
   130	        String trackingNumber = orderShipment.getTrackingNumber();
   131	        Long shipmentId = orderShipment.getId();
   132	
   133	        if (trackingNumber == null || trackingNumber.isBlank()) {
   134	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
   135	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
   136	        }
   137	
   138	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
   139	                shipmentId, trackingNumber, orderShipment.getStatus());
   140	
   141	        Page page = null;
   142	        try {
   143	            // browserManager를 통해 페이지 생성
   144	            page = browserManager.newPage();
   145	            if (page == null) {
   146	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
   147	            }
   148	
   149	            // 타임아웃 설정
   150	            page.setDefaultTimeout(TIMEOUT_MS);
   151	
   152	            // 배송 추적 URL로 이동
   153	            String url = TRACKING_URL_PREFIX + trackingNumber;
   154	            log.debug("배송 조회 페이지로 이동: {}", url);
   155	            page.navigate(url);
   156	
   157	            // 배송 상태 테이블 로드 대기
   158	            log.debug("배송 상태 테이블 로드 대기");
   159	            page.waitForSelector(STATUS_SELECTOR);
   160	
   161	            // 최종 HTML 가져오기
   162	            String renderedHtml = page.content();
   163	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
   164	
   165	            // HTML 파싱하여 배송 상태 추출
   166	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
   167	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
   168	
   169	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
   170	                    shipmentId, statusText, newStatus);
   171	
   172	            // 현재 상태와 동일한 경우 중복 처리 방지
   173	            if (orderShipment.getStatus() == newStatus) {
   174	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   175	                        shipmentId, newStatus);
   176	                return orderShipment;
   177	            }
   178	
   179	            // 상태에 따른 처리
   180	            if (newStatus == ShipmentStatus.DELIVERED) {
   181	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
   182	                        shipmentId, orderShipment.getOrder().getId());
   183	
   184	                // 배송 상태 업데이트
   185	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
   186	
   187	                // 주문 완료 처리 및 알림
   188	                orderService.completeOrder(orderShipment.getOrder().getId());
   189	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   190	
   191	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
   192	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
   193	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
   194	
   195	            } else {
   196	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   197	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
   198	            }
   199	
   200	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
   201	                    shipmentId, orderShipment.getStatus());
   202	
   203	            return orderShipment;
   204	
   205	        } catch (Exception e) {
   206	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   207	                    shipmentId, trackingNumber, e.getMessage(), e);
   208	
   209	            // ShipmentException 타입이 아닌 경우 래핑
   210	            if (!(e instanceof ShipmentException)) {
   211	                throw new ShipmentException(
   212	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   213	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   214	                        e
   215	                );
   216	            }
   217	            throw e;
   218	        } finally {
   219	            // 페이지 리소스 해제
   220	            if (page != null) {
   221	                try {
   222	                    page.close();
   223	                    log.debug("페이지 리소스 해제 완료");
   224	                } catch (Exception e) {
   225	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
   226	                }
   227	            }
   228	        }
   229	    }
   230	
   231	    /**
   232	     * HTML에서 배송 상태를 파싱합니다.
   233	     *
   234	     * @param html 파싱할 HTML 문자열
   235	     * @param trackingNumber 로깅용 운송장 번호
   236	     * @return 배송 상태 문자열
   237	     * @throws ShipmentException 파싱 실패 시 발생
   238	     */
   239	    private String parseStatusFromHtml(String html, String trackingNumber) {
   240	        try {
   241	            Document doc = Jsoup.parse(html);
   242	            Elements rows = doc.select(STATUS_SELECTOR);
   243	
   244	            if (rows.isEmpty()) {
   245	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
   246	                throw new ShipmentException(
   247	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   248	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
   249	                );
   250	            }
   251	
   252	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
   253	            String statusText = rows.last().select("td").get(4).text().trim();
   254	
   255	            if (statusText.isEmpty()) {
   256	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   257	                throw new ShipmentException(
   258	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   259	                        "배송 상태 정보를 찾을 수 없습니다."
   260	                );
   261	            }
   262	
   263	            return statusText;
   264	
   265	        } catch (IndexOutOfBoundsException e) {
   266	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   267	            throw new ShipmentException(
   268	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   269	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
   270	                    e
   271	            );
   272	        } catch (Exception e) {
   273	            if (e instanceof ShipmentException) {
   274	                throw (ShipmentException) e;
   275	            }
   276	
   277	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   278	            throw new ShipmentException(
   279	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   280	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
   281	                    e
   282	            );
   283	        }
   284	    }
   285	
   286	    /**
   287	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
   288	     *
   289	     * @param statusText 배송사 상태 텍스트
   290	     * @return 매핑된 ShipmentStatus
   291	     */
   292	    private ShipmentStatus mapToShipmentStatus(String statusText) {
   293	        return switch (statusText) {
   294	            case "배송완료" -> ShipmentStatus.DELIVERED;
   295	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
   296	            default -> ShipmentStatus.IN_TRANSIT;
   297	        };
   298	    }
   299	}package com.fream.back.domain.shipment.config;
   300	
   330	
   331	
   332	/**
   333	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
   334	 */
   335	@Slf4j
   336	@Configuration
   337	@RequiredArgsConstructor
   338	public class UpdateShipmentStatusesJobConfig {
   339	
   340	    private final JobRepository jobRepository;
   341	    private final PlatformTransactionManager transactionManager;
   342	    private final EntityManagerFactory entityManagerFactory;
   343	
   344	    private final OrderShipmentRepository orderShipmentRepository;
   345	    private final NotificationCommandService notificationService;
   346	    private final OrderShipmentCommandService orderService;
   347	    private final CjTrackingPlaywright cjTrackingPlaywright;
   348	
   349	    private static final int CHUNK_SIZE = 50;
   350	    private static final int SKIP_LIMIT = 50;
   351	
   352	    @Bean
   353	    public Job updateShipmentStatusesJob() {
   354	        log.info("배송 상태 업데이트 작업 구성");
   355	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
   356	                .start(updateShipmentStatusesStep())
   357	                .build();
   358	    }
   359	
   360	    @Bean
   361	    public Step updateShipmentStatusesStep() {
   362	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
   363	
   364	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
   365	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
   366	                .reader(shipmentItemReader())
   367	                .processor(new ShipmentItemProcessor(
   368	                        playwrightBrowserManager(), // Bean or new
   369	                        notificationService,
   370	                        orderService
   371	                ))
   372	                .writer(shipmentJpaItemWriter())
   373	                .faultTolerant()
   374	                .skip(Exception.class)
   375	                .skipLimit(SKIP_LIMIT)
   376	                .listener(shipmentSkipListener())
   377	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
   378	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
   379	                .build();
   380	    }
   381	
   382	    /**
   383	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
   384	     */
   385	    @Bean
   386	    @StepScope
   387	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
   388	        log.debug("배송 상태 업데이트 ItemReader 구성");
   389	        return new JpaPagingItemReaderBuilder<OrderShipment>()
   390	                .name("shipmentItemReader")
   391	                .entityManagerFactory(entityManagerFactory)
   392	                .pageSize(CHUNK_SIZE)
   393	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
   394	                .build();
   395	    }
   396	
   397	    /**
   398	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
   399	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
   400	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
   401	     */
   402	    @Bean
   403	    @StepScope
   404	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
   405	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
   406	
   407	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
   408	        return orderShipment -> {
   409	            String trackingNumber = orderShipment.getTrackingNumber();
   410	            Long shipmentId = orderShipment.getId();
   411	
   412	            if (trackingNumber == null || trackingNumber.isBlank()) {
   413	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
   414	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
   415	            }
   416	
   417	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
   418	                    shipmentId, trackingNumber, orderShipment.getStatus());
   419	
   420	            try {
   421	                // 2-1) 현재 상태 가져오기
   422	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
   423	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
   424	
   425	                // 2-2) 매핑
   426	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
   427	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
   428	
   429	                // 현재 상태와 동일한 경우 중복 처리 방지
   430	                if (orderShipment.getStatus() == newStatus) {
   431	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   432	                            shipmentId, newStatus);
   433	                    return orderShipment;
   434	                }
   435	
   436	                // 2-3) 상태에 따른 처리
   437	                if (newStatus == ShipmentStatus.DELIVERED) {
   438	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
   439	                            shipmentId, orderShipment.getOrder().getId());
   440	
   441	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
   442	                    // Order 상태도 COMPLETED 로 변경
   443	                    orderService.completeOrder(orderShipment.getOrder().getId());
   444	                    // 알림 발송
   445	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   446	                }
   447	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
   448	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
   449	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
   450	                    // 필요시 알림, 로직 추가
   451	                }
   452	                else {
   453	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   454	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
   455	                }
   456	
   457	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
   458	                return orderShipment; // Writer로 넘김
   459	
   460	            } catch (Exception e) {
   461	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   462	                        shipmentId, trackingNumber, e.getMessage(), e);
   463	
   464	                // ShipmentException 타입이 아닌 경우 래핑
   465	                if (!(e instanceof ShipmentException)) {
   466	                    throw new ShipmentException(
   467	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   468	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   469	                            e
   470	                    );
   471	                }
   472	                throw e;
   473	            }
   474	        };
   475	    }
   476	
   477	    /**
   478	     * CJ대한통운 배송 상태 조회를 위한 메서드
   479	     *
   480	     * @param trackingNumber 운송장 번호
   481	     * @return 배송 상태 텍스트
   482	     * @throws Exception 조회 실패 시 발생
   483	     */
   484	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
