218	     */
219	    @Transactional
220	    public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
221	                                    boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
222	        try {
223	            // 입력값 검증
224	            if (buyer == null) {
225	                throw new InvalidOrderDataException("구매자 정보가 없습니다.");
226	            }
227	            if (saleBid == null) {
228	                throw new SaleBidNotFoundException("판매 입찰 정보가 없습니다.");
229	            }
230	            if (addressId == null) {
231	                throw new InvalidOrderDataException("배송지 정보가 없습니다.");
232	            }
233	            if (paymentRequest == null) {
234	                throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
235	            }
236	
237	            // 1. 주소 조회
238	            AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
239	
240	            // 2. Order 생성
241	            Order order = Order.builder()
242	                    .user(buyer)
243	                    .totalAmount(saleBid.getBidPrice())
244	                    .status(OrderStatus.PENDING_PAYMENT)
245	                    .build();
246	
247	            order = orderRepository.save(order);
248	
249	            // PaymentRequest에 OrderId 설정
250	            paymentRequest.setOrderId(order.getId());
251	            log.debug("결제 요청 정보: {}", paymentRequest);
252	
253	            // 3. OrderItem 추가
254	            try {
255	                OrderItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
256	                order.addOrderItem(orderItem);
257	            } catch (Exception e) {
258	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
259	                throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
260	            }
261	
262	            // 4. 배송 정보 생성 및 연관 설정
263	            try {
264	                OrderShipment orderShipment = orderShipmentCommandService.createOrderShipment(
265	                        order,
266	                        address.getRecipientName(),
267	                        address.getPhoneNumber(),
268	                        address.getZipCode(),
269	                        address.getAddress()
270	                );
271	                order.assignOrderShipment(orderShipment);
272	            } catch (Exception e) {
273	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
274	                throw new OrderShipmentProcessingFailedException("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
275	            }
276	
277	            try {
278	                // 판매 입찰 상태 업데이트
279	                saleBid.assignOrder(order);
280	                saleBid.updateStatus(com.fream.back.domain.sale.entity.BidStatus.MATCHED);
281	
282	                // 변경 내용 강제 반영
283	                entityManager.flush();
284	            } catch (Exception e) {
285	                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
286	                throw new OrderBidMatchingFailedException("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
287	            }
288	
289	            // Sale의 isWarehouseStorage 확인 후 상태 변경
290	            try {
291	                Sale sale = saleBid.getSale();
292	                if (sale != null && sale.isWarehouseStorage()) {
293	                    warehouseStorageCommandService.updateWarehouseStatus(sale, WarehouseStatus.ASSOCIATED_WITH_ORDER);
294	                }
295	            } catch (WarehouseStorageException e) {
296	                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
297	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
298	            } catch (Exception e) {
299	                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
300	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
301	            }
302	
303	            // 결제 처리
304	            try {
305	                paymentCommandService.processPayment(order, buyer, paymentRequest);
306	            } catch (Exception e) {
307	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
308	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
309	            }
310	
311	            return order;
312	        } catch (Exception e) {
313	            if (e instanceof OrderException) {
314	                throw e;
315	            }
316	            log.error("즉시 구매 주문 생성 중 오류 발생: {}", e.getMessage(), e);
317	            throw new OrderCreationFailedException("즉시 구매 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
318	        }
319	    }
