    private void sendNotifications(Order order, Sale sale) {
        try {
            User buyer = order.getUser();
            if (buyer != null) {
                notificationCommandService.createNotification(
                        buyer.getId(),
                        NotificationCategory.SHOPPING,
                        NotificationType.BID,
